"""Builds gizmos/Flux3Klein.nk (a single Group) with Nuke's own API, so the .nk is valid by construction.

    "L:/Apps/Nuke16.1v4/Nuke16.1.exe" -t L:/Nuke/tools/comfy/build/build_flux3klein.py

Edit this script, not the .nk, and rebuild.
"""
import os

import nuke

HERE = os.path.dirname(os.path.abspath(__file__))
OUT = os.path.join(HERE, "..", "gizmos", "Flux3Klein.nk").replace("\\", "/")

HEADER = """# Flux3Klein - paint, replace or erase part of one frame through ComfyUI (FLUX 3 Image Klein, json/Flux3Klein.json)
# Generated by build/build_flux3klein.py: edit that script and rebuild, not this file.
# Generate crops the current frame around the edit mask (plus context), sends it as a half-float EXR in the script's
# working space with the mask in alpha, and Klein repaints only under the mask. Fit to Plate matches colour and grain,
# big crops come back through SeedVR2, and the patch is keymixed over the untouched Source through the grown +
# feathered mask held at the generated frame. Every result is kept: pick one in Version.
# Inputs: Source, Mask (Roto, a keyer...: pick the channel), Strokes (RGBA paint as a guide), Ref1-Ref4.
# Needs NukeComfy on the plugin path and a ComfyUI (COMFY_URL) with ComfyUI-EXR-ACEScg, ComfyUI-PlateFit,
# ainvfx-paintaplate and SeedVR2. Without them the group still evaluates and shows the last result.
# Target: Nuke 16.1. Import with the NukeComfy menu or nuke.nodePaste(path).
"""


def knob(group, k, value=None, **flags):
    group.addKnob(k)
    if value is not None:
        k.setValue(value)
    for name, on in flags.items():
        k.setFlag(getattr(nuke, name)) if on else k.clearFlag(getattr(nuke, name))
    return k


def tooltip(k, text):
    k.setTooltip(text)
    return k


def build():
    for n in nuke.allNodes():
        nuke.delete(n)
    g = nuke.nodes.Group(name="Flux3Klein", tile_color=0x4a7a9bff, label="[value status]")

    # ---- Edit tab
    knob(g, nuke.Tab_Knob("edit_tab", "Edit"))
    knob(g, nuke.String_Knob("template", ""), "Flux3Klein", INVISIBLE=True)
    tooltip(knob(g, nuke.Enumeration_Knob("mode", "Mode", ["Replace or add", "Erase"])),
            "Replace or add: Klein paints what the prompt describes inside the mask.\n"
            "Erase: removes what is inside the mask and continues the background (the prompt can name the object).")
    tooltip(knob(g, nuke.Multiline_Eval_String_Knob("prompt_pos", "Prompt"), "a bright red enamel star emblem"),
            "What to paint inside the mask (Replace), or what to remove (Erase, optional). Just the object: the tool "
            "writes the full instruction for Klein. Ref1 is <ref_image_1> ... Ref4 is <ref_image_4> if you use them.")
    tooltip(knob(g, nuke.Link_Knob("mask_channel", "Mask channel")), "Channel of the Mask input that marks the edit (white = edit).")
    g["mask_channel"].setLink("MaskSel.from0")
    knob(g, nuke.Int_Knob("seed", "Seed"), 7)
    tooltip(knob(g, nuke.Int_Knob("steps", "Steps"), 16), "Steps of the first Klein pass. 16 is the distilled model's own setting.")
    g["steps"].clearFlag(nuke.STARTLINE)
    tooltip(knob(g, nuke.Int_Knob("edit_grow", "Edit grow (px)"), 16),
            "How far around the mask Klein may repaint, in working pixels (Size tab). Needs a new Generate.")
    knob(g, nuke.Text_Knob("edit_div", ""))
    knob(g, nuke.PyScript_Knob("generate", "Generate",
                               "import NukeComfy.python.flux3klein\nNukeComfy.python.flux3klein.generate(nuke.thisNode())"))
    knob(g, nuke.Boolean_Knob("show_result", "Show result"), True, STARTLINE=False)
    tooltip(knob(g, nuke.Enumeration_Knob("version", "Version", [" "])), "Every Generate adds a version; pick the one to show.")
    knob(g, nuke.String_Knob("status", "Status"), "Idle")
    for name in ("has_result",):
        knob(g, nuke.Boolean_Knob(name, ""), False, INVISIBLE=True)
    knob(g, nuke.String_Knob("versions_data", ""), "[]", INVISIBLE=True)
    for name in ("patch_x", "patch_y", "patch_frame"):
        knob(g, nuke.Int_Knob(name, ""), 0, INVISIBLE=True)

    # ---- Strokes tab
    knob(g, nuke.Tab_Knob("strokes_tab", "Strokes"))
    tooltip(knob(g, nuke.Boolean_Knob("use_strokes", "Use strokes"), True),
            "Paint a rough shape in colour (RotoPaint, RGBA) into the Strokes input: Klein turns it into what the "
            "prompt says, keeping its shape and colours. The strokes' alpha is added to the edit mask.")
    knob(g, nuke.Text_Knob("strokes_info", "", "Connect RGBA strokes to the Strokes input (e.g. a RotoPaint on black).\n"
                                                "They are merged over Source for Klein; the plate itself is not changed."))

    # ---- References tab
    knob(g, nuke.Tab_Knob("refs_tab", "References"))
    knob(g, nuke.Text_Knob("refs_info", "", "Connect up to 4 images to Ref1-Ref4 (a product, a texture, a look).\n"
                                             "Name them in the prompt: 'the jacket from <ref_image_1>'.\n"
                                             "Each is sent at about 1 MP; every reference adds time."))

    # ---- Size tab
    knob(g, nuke.Tab_Knob("size_tab", "Size"))
    tooltip(knob(g, nuke.Enumeration_Knob("region", "Region", ["Crop to mask", "Full frame"])),
            "Crop to mask sends only the mask's area plus context, so a small edit on a 4K plate keeps full detail.")
    tooltip(knob(g, nuke.Double_Knob("context", "Context (%)"), 50),
            "Area around the mask sent with it, in % of the mask's size (at least 64 px). More context: better fit, less detail.")
    g["context"].setRange(0, 200)
    tooltip(knob(g, nuke.Double_Knob("megapixels", "Working size (MP)"), 2.0),
            "Size Klein refines at. The crop is scaled to it and back. On a 12 GB RTX 3060 a 2 MP edit takes about a minute.")
    g["megapixels"].setRange(0.5, 4)
    tooltip(knob(g, nuke.Double_Knob("refine", "Refine strength"), 0.35),
            "Klein works in two passes: a quick one at about 0.6 MP finds the edit, then a refine at the working size\n"
            "redraws it with this much freedom (8 steps). Lower keeps the quick pass, higher adds detail and change.")
    g["refine"].setRange(0.1, 0.8)
    tooltip(knob(g, nuke.Enumeration_Knob("upscale", "Upscale", ["Auto", "SeedVR", "Resize"])),
            "Back to the crop's size. Auto uses SeedVR2 when the crop is more than 1.25x the working size, else a resize.")
    tooltip(knob(g, nuke.Enumeration_Knob("seedvr_model", "SeedVR model", ["3B (fast)", "7B sharp (slow)"])),
            "3B GGUF fits the card. 7B sharp is 16 GB and streams from RAM: much slower.")

    # ---- Colour tab
    knob(g, nuke.Tab_Knob("colour_tab", "Colour"))
    tooltip(knob(g, nuke.Enumeration_Knob("color", "Plate primaries", ["Auto", "ACEScg", "Linear Rec.709"])),
            "Primaries of the script's working space (the tool always sends scene-linear data, untouched).\n"
            "Auto: ACEScg when the OCIO working space is ACEScg, else Linear Rec.709 (Nuke's default 'linear').")
    tooltip(knob(g, nuke.Enumeration_Knob("match_color", "Colour match", ["Auto", "On", "Off"])),
            "Match the edit's colour and exposure to the plate at its edge. Auto: on for Replace, off for Erase.")
    tooltip(knob(g, nuke.Double_Knob("grain", "Grain"), 1.0), "Add grain up to the plate's level. 0 adds none.")
    g["grain"].setRange(0, 2)

    # ---- Output tab
    knob(g, nuke.Tab_Knob("output_tab", "Output"))
    tooltip(knob(g, nuke.Int_Knob("comp_grow", "Grow (px)"), 8), "Grows the mask used to comp the patch. No new Generate needed.")
    tooltip(knob(g, nuke.Double_Knob("feather", "Feather (px)"), 6), "Softens the comp edge. No new Generate needed.")
    g["feather"].setRange(0, 50)

    g["knobChanged"].setValue("try:\n    import NukeComfy.python.flux3klein as f\n    f.knob_changed(nuke.thisNode(), nuke.thisKnob())\n"
                              "except ImportError:\n    pass")

    with g:
        src = nuke.nodes.Input(name="Source", number=0, xpos=0, ypos=-400)
        mask = nuke.nodes.Input(name="Mask", number=1, xpos=300, ypos=-400)
        strokes = nuke.nodes.Input(name="Strokes", number=2, xpos=600, ypos=-400)
        for i in range(4):
            nuke.nodes.Input(name=f"Ref{i + 1}", number=3 + i, xpos=900 + 120 * i, ypos=-400)

        sel = nuke.nodes.Copy(name="MaskSel", from0="rgba.alpha", to0="rgba.alpha", xpos=300, ypos=-320)
        sel.setInput(0, mask)
        sel.setInput(1, mask)
        edit = nuke.nodes.Merge2(name="EditMask", operation="max", Achannels="alpha", Bchannels="alpha", output="alpha",
                                 xpos=300, ypos=-240)
        edit.setInput(0, sel)
        edit.setInput(1, strokes)
        edit["disable"].setExpression("!parent.use_strokes")

        guide = nuke.nodes.Merge2(name="Guide", operation="over", xpos=600, ypos=-160)
        guide.setInput(0, src)
        guide.setInput(1, strokes)
        send = nuke.nodes.Copy(name="SendSource", from0="rgba.alpha", to0="rgba.alpha", xpos=150, ypos=-160)
        send.setInput(0, src)
        send.setInput(1, edit)
        crop = nuke.nodes.Crop(name="CropBox", reformat=True, crop=True, xpos=150, ypos=-80)
        crop.setInput(0, send)
        nuke.nodes.NoOp(name="SendCrop", xpos=150, ypos=-20).setInput(0, crop)
        gcrop = nuke.nodes.Crop(name="GuideCrop", reformat=True, crop=True, xpos=600, ypos=-80)
        gcrop["box"].setExpression("CropBox.box")
        gcrop.setInput(0, guide)

        hold = nuke.nodes.FrameHold(name="HoldMask", xpos=300, ypos=0)
        hold["firstFrame"].setExpression("parent.patch_frame")
        hold.setInput(0, edit)
        grow = nuke.nodes.FilterErode(name="Grow", channels="alpha", xpos=300, ypos=60)
        grow["size"].setExpression("-parent.comp_grow")
        grow.setInput(0, hold)
        feather = nuke.nodes.Blur(name="Feather", channels="alpha", xpos=300, ypos=120)
        feather["size"].setExpression("parent.feather")
        feather.setInput(0, grow)

        read = nuke.nodes.Read(name="Result", raw=True, on_error="black", xpos=-200, ypos=0)
        read["disable"].setExpression("!parent.has_result")
        place = nuke.nodes.Transform(name="Place", xpos=-200, ypos=80)
        place["translate"].setExpression("parent.patch_x", 0)
        place["translate"].setExpression("parent.patch_y", 1)
        place.setInput(0, read)

        comp = nuke.nodes.Keymix(name="Comp", channels="rgb", xpos=0, ypos=180)
        comp.setInput(0, src)  # B
        comp.setInput(1, place)  # A
        comp.setInput(2, feather)  # mask
        show = nuke.nodes.Switch(name="ShowResult", xpos=0, ypos=260)
        show.setInput(0, src)
        show.setInput(1, comp)
        show["which"].setExpression("parent.show_result * parent.has_result")
        nuke.nodes.Output(name="Output1", xpos=0, ypos=340).setInput(0, show)

    for n in nuke.allNodes():
        n.setSelected(False)
    g.setSelected(True)
    nuke.nodeCopy(OUT)
    with open(OUT, encoding="utf-8") as f:
        body = f.read()
    with open(OUT, "w", encoding="utf-8", newline="\n") as f:
        f.write(HEADER + body)
    print("wrote", OUT)


build()
